def add_entity(table,module,definition,fields,req='REQ-036'):
 eid=f'ENT-{len(entities)+1:03}'
 retention='30 days after delivery; 90 days for failed events; proposed owner policy' if table=='outbox_event' else 'Configuration lifetime; actor identifiers unlinked after 24 months inactivity or earlier approved erasure'
 entities.append(dict(id=eid,table=table,module=module,definition=definition,owner=module+' owner',deletion='Soft delete plus scheduled erasure',retention=retention,requirement=req,source='D3 pp.9-10; step17 design'))
 fields=[('id','bigint','id',False,'Surrogate row identifier',1,None)]+fields+[
  ('created_at','timestamptz','timestamp',False,'UTC creation instant',STAMP,None),
  ('created_by','bigint','id',True,'Authenticated actor, or NULL for bootstrap',1,'app_user'),
  ('updated_at','timestamptz','timestamp',False,'UTC latest permitted change',STAMP,None),
  ('updated_by','bigint','id',True,'Authenticated actor, or NULL for bootstrap',1,'app_user'),
  ('deleted_at','timestamptz','timestamp',True,'Soft deletion instant, NULL while active',None,None)]
 for name,dtype,domain,nullable,definition,example,parent in fields:
  add_attribute(table,name,dtype,domain,nullable,definition,example,parent,eid)
 sample[table]=[]

def add_attribute(table,name,dtype,domain,nullable,definition,example,parent=None,eid=None):
 if eid is None:eid=next(e['id'] for e in entities if e['table']==table)
 cls='Personal' if parent=='app_user' else ('Sensitive' if domain in ['token','secret'] else 'Internal')
 attr=dict(id=f'ATT-{len(attrs)+1:04}',entity_id=eid,table=table,column=name,type=dtype,domain=domain,nullable=nullable,null_reason='NULL only before the optional event or bootstrap identity is known' if nullable else 'Not nullable',example=example,definition=definition,classification=cls,storage='Stored',owner=next(e['owner'] for e in entities if e['table']==table),validation='Typed scalar; dictionary-defined length/range; FK where applicable',default='GENERATED BY DEFAULT AS IDENTITY' if name=='id' else ('false' if domain=='bool' else ('CURRENT_TIMESTAMP' if name in ['created_at','updated_at'] else 'No implicit default')),rule='BR-001; BR-002; BR-003; BR-004; BR-005',source='D1 p.4; D3 p.10; step17 refinement')
 attrs.append(attr)
 if parent:rels.append(dict(id=f'REL-{len(rels)+1:03}',child=table,column=name,parent=parent,child_to_parent='0..1' if nullable else '1',parent_to_child='0..N',optional=nullable,on_update='RESTRICT',on_delete='RESTRICT',enforcement='Database FOREIGN KEY',reason='Explicit v2 model relationship',source='D3 p.10; step17 refinement'))

