# Business rules added by the refinement. Positive and negative payloads execute below.
def new_rule(title,table,statement,enforcement,owner,req,positive,negative,validator):
 rid=f'BR-{len(rules)+1:03}'
 r=dict(id=rid,title=title,table=table,statement=statement,enforcement=enforcement,owner=owner,requirement=req,positive=positive,negative=negative,source='D1 pp.2-6; D3 p.10; step17 refinement',proof='Contract executed; engine proof separately recorded')
 rules.append(r);new_rules.append((r,validator));return rid

new_rule('Hierarchy cycle','organisation','An organisation cannot be its own ancestor','Recursive hierarchy guard in owning service; database self-parent CHECK','Organisation owner','REQ-007',[1,2,[]],[1,1,[]],lambda x:x[0]!=x[1] and x[0] not in x[2])
new_rule('Outbox delivery','outbox_event','Delivery cannot precede availability; retries retain original event key','Timestamp CHECK; unique event_key; transaction-level producer','Integration owner','REQ-036',[2,3,1],[3,2,1],lambda x:x[1]>=x[0] and x[2]>=0)
new_rule('Question option scope','job_question_option,application_answer','An answer option must belong to the application question','Unique(question,code), FK and submission validation','Jobs owner','REQ-009',[1,1],[1,2],lambda x:x[0]==x[1])
new_rule('Currency consistency','wallet_ledger_entry','Ledger currency equals wallet currency','Composite FK(wallet_id,currency_code)','Commerce owner','REQ-015',['INR','INR'],['INR','USD'],lambda x:x[0]==x[1])
new_rule('Ledger reversal link','wallet_ledger_entry','A correction references a different original entry on the same wallet','CHECK original<>id plus reversal-service verification','Commerce owner','REQ-015',[2,1,1,1],[1,1,1,1],lambda x:x[0]!=x[1] and x[2]==x[3])
new_rule('Effective recruiter membership','recruiter_membership','Access requires current membership in the requirement organisation','Half-open temporal membership predicate','Organisation owner','REQ-007',[1,1,0,10,5],[1,2,0,10,5],lambda x:x[0]==x[1] and x[2]<=x[4]<x[3])
new_rule('Required answer','application_answer','Required question cannot be skipped or answered by another job application','Submission transaction verifies question requirement and job pair','Jobs owner','REQ-009',[True,'synthetic answer',1,1],[True,'',1,1],lambda x:(not x[0] or bool(x[1])) and x[2]==x[3])
new_rule('Licence reduction','licence','Reducing limits cannot invalidate active seats or sessions','Administrative transaction locks licence and validates active counts','Licensing owner','REQ-024',[3,2,2,1],[1,2,2,1],lambda x:x[0]>=x[2] and x[1]>=x[3])
new_rule('Session release','user_session','Ended, revoked or expired sessions do not consume capacity','Login trigger active-count predicate','Licensing owner','REQ-025',[None,20,10],[None,9,10],lambda x:x[0] is None and x[1]>x[2])
new_rule('Refund currency','refund','Refund uses captured payment currency and cannot exceed captured amount','Refund transaction locks captured payment; verify signed provider outcome','Commerce owner','REQ-028',['INR','INR',100,20],['USD','INR',100,20],lambda x:x[0]==x[1] and Decimal(str(x[3]))<=Decimal(str(x[2])))
new_rule('Translation fallback','ui_translation','Resolve requested language then English; never display a raw key','Translation resolver in access layer','Master owner','REQ-032',['hi',{'en':'Name','hi':'नाम'}],['hi',{}],lambda x:bool(x[1].get(x[0]) or x[1].get('en')))
new_rule('Money sign','wallet_ledger_entry','A debit is negative and a recharge is positive','Reference-aware ledger trigger and amount-domain contract','Commerce owner','REQ-015',['debit','-10.00'],['debit','10.00'],lambda x:(Decimal(x[1])<0 if x[0]=='debit' else Decimal(x[1])>0))
new_rule('Reservation status','gig_assignment','Only pending_handoff and active assignments reserve worker time','Before-write status-to-blocks_window trigger','Gig owner','REQ-021',['active',True],['cancelled',True],lambda x:x[1]==(x[0] in ['pending_handoff','active']))
new_rule('Consent withdrawal','consent_record,notification_delivery','No new delivery after a purpose consent was withdrawn','Check consent at delivery time, not only at enqueue','Privacy owner','REQ-016',[1,None,10],[1,5,10],lambda x:x[0]<=x[2] and (x[1] is None or x[1]>x[2]))
new_rule('Soft deletion visibility','candidate_profile,job_requirement','Default reads exclude soft-deleted business records','Access-layer predicate and row policies on protected tables','Data owner','REQ-035',None,STAMP,lambda x:x is None)
new_rule('No reverse gig bid','gig_application','Only the worker submits a gig application; requester makes the decision','Authenticated principal-to-worker ownership predicate','Gig owner','REQ-020',[1,1],[1,2],lambda x:x[0]==x[1])

