def q(s):
 assert re.fullmatch(r'[a-z][a-z0-9_]*',s),s
 return '"'+s+'"'
def lit(v):
 if v is None:return 'NULL'
 if type(v) is bool:return 'TRUE' if v else 'FALSE'
 if isinstance(v,(int,float)):return str(v)
 return "'"+str(v).replace("'","''")+"'"
def objname(prefix,table,columns):
 name=prefix+'_'+table+'_'+'_'.join(columns)
 return name if len(name)<=63 else name[:53]+'_'+hashlib.sha256(name.encode()).hexdigest()[:8]

check_expr=defaultdict(list)
for t,columns in by_table.items():
 names={a['column'] for a in columns}
 for a in columns:
  c=q(a['column']);d=a['domain']
  if d=='count':check_expr[t].append(f'{c} >= 0')
  elif d=='percentage':check_expr[t].append(f'{c} BETWEEN 0 AND 100')
  elif d=='rating':check_expr[t].append(f'{c} BETWEEN 1 AND 5')
  elif d=='latitude':check_expr[t].append(f'{c} BETWEEN -90 AND 90')
  elif d=='longitude':check_expr[t].append(f'{c} BETWEEN -180 AND 180')
  elif d=='money' and a['column']!='signed_amount':check_expr[t].append(f'{c} >= 0')
 for start,end in [('start_date','end_date'),('valid_from','valid_to'),('start_at','end_at')]:
  if {start,end}<=names:check_expr[t].append(f'{q(end)} IS NULL OR {q(end)} >= {q(start)}')
 if t=='app_user':check_expr[t].append('email = lower(email)')
 if t=='job_requirement':check_expr[t]+=['positions > 0','salary_min <= salary_max','(salary_min IS NULL AND salary_max IS NULL AND currency_code IS NULL) OR (salary_min IS NOT NULL AND salary_max IS NOT NULL AND currency_code IS NOT NULL)']
 if t=='licence':check_expr[t]+=['max_user_count > 0','max_device_per_user > 0']
 if t=='organisation':check_expr[t].append('parent_organisation_id IS NULL OR parent_organisation_id <> id')
 if t=='blocking_entry':check_expr[t].append('(blocked_app_user_id IS NOT NULL) <> (blocked_organisation_id IS NOT NULL)')
 if t=='user_session':check_expr[t]+=['last_activity_at >= started_at','expires_at > last_activity_at','ended_at IS NULL OR ended_at >= started_at']
